sys_script_client.script:
function onSubmit() {
    // Final validation before form submission
    try {
        var stockName = g_form.getValue('stock_name');
        var buyingPrice = g_form.getValue('buying_price');
        var stopLoss = g_form.getValue('stop_loss');
        var tradeDate = g_form.getValue('date');

        // Required field validation
        if (!stockName || stockName.trim() === '') {
            g_form.addErrorMessage('❌ Stock name is required');
            return false;
        }

        if (!buyingPrice || buyingPrice.trim() === '') {
            g_form.addErrorMessage('❌ Buying price is required');
            return false;
        }

        if (!stopLoss || stopLoss.trim() === '') {
            g_form.addErrorMessage('❌ Stop loss is required');
            return false;
        }

        // Numeric validation
        var buying = parseFloat(buyingPrice);
        var stop = parseFloat(stopLoss);

        if (isNaN(buying) || buying <= 0) {
            g_form.addErrorMessage('❌ Buying price must be a positive number');
            return false;
        }

        if (isNaN(stop) || stop <= 0) {
            g_form.addErrorMessage('❌ Stop loss must be a positive number');
            return false;
        }

        // Logical validation
        if (stop >= buying) {
            g_form.addErrorMessage('❌ Stop loss must be lower than buying price');
            return false;
        }

        // Risk percentage validation
        var riskPercentage = ((buying - stop) / buying) * 100;

        if (riskPercentage > 25) {
            var confirmHighRisk = confirm(
                '⚠️ HIGH RISK TRADE DETECTED \n\n' +
                'Risk Level: ' + riskPercentage.toFixed(1) + '%\n' +
                'Risk Amount: $' + (buying - stop).toFixed(2) + '\n\n' +
                'This exceeds the recommended 25% risk threshold.\n' +
                'Consider adjusting your stop loss to reduce risk.\n\n' +
                'Do you want to proceed with this high-risk trade?'
            );

            if (!confirmHighRisk) {
                g_form.showFieldMsg('stop_loss', '⚠️ Consider a tighter stop loss to reduce risk', 'warning');
                return false;
            }
        }

        // Stock name format validation
        var hasTickerPattern = /\([A-Z]{1,5}\)$/.test(stockName.trim());

        if (!hasTickerPattern) {
            var confirmFormat = confirm(
                '📝 STOCK NAME FORMAT NOTICE\n\n' +
                'Current: ' + stockName + '\n' +
                'Recommended format: Company Name (TICKER)\n' +
                'Example: Apple Inc. (AAPL)\n\n' +
                'Proper format helps with:\n' +
                '• Trade tracking and reporting\n' +
                '• Integration with market data\n' +
                '• Portfolio analysis\n\n' +
                'Do you want to proceed with the current format?'
            );

            if (!confirmFormat) {
                g_form.showFieldMsg('stock_name', '💡 Use format: Company Name (TICKER)', 'info');
                return false;
            }
        }

        // Date validation
        if (tradeDate) {
            var today = new Date();
            var selectedDate = new Date(tradeDate);

            if (selectedDate > today) {
                var confirmFutureDate = confirm(
                    '📅 FUTURE DATE DETECTED\n\n' +
                    'Trade date: ' + tradeDate + '\n' +
                    'Today: ' + today.toISOString().split('T')[0] + '\n\n' +
                    'Are you planning a future trade or is this a mistake?'
                );

                if (!confirmFutureDate) {
                    g_form.showFieldMsg('date', '📅 Please verify the trade date', 'warning');
                    return false;
                }
            }
        }

        // Success message and logging
        g_form.addInfoMessage('✅ Trade validation passed - submitting record...');

        // Log successful submission for audit
        console.log('Trade Book submission validated:', {
            stock: stockName,
            buyingPrice: '$' + buying.toFixed(2),
            stopLoss: '$' + stop.toFixed(2),
            riskPercentage: riskPercentage.toFixed(2) + '%',
            riskAmount: '$' + (buying - stop).toFixed(2),
            date: tradeDate || 'Not specified'
        });

        return true;

    } catch (error) {
        g_form.addErrorMessage('❌ Validation error: ' + error.message);
        console.error('Trade Book onSubmit error:', error);
        return false;
    }
}
